import requests
from requests.exceptions import InvalidURL, MissingSchema

# Test various edge cases
tests = [
    ('http://.example.com', InvalidURL),  # Leading dot
    ('http://example..com', InvalidURL),  # Double dot
    ('http://localhost', None),  # Valid simple hostname
    ('http://127.0.0.1', None),  # Valid IP address
    ('http://[::1]', None),  # Valid IPv6 address
]

for url, expected_exception in tests:
    try:
        r = requests.get(url, timeout=0.1)
        if expected_exception:
            print(f'FAIL: {url} should have raised {expected_exception.__name__}')
        else:
            print(f'PASS: {url} connected (or timed out normally)')
    except expected_exception if expected_exception else () as e:
        print(f'PASS: {url} raised {type(e).__name__} as expected')
    except (requests.exceptions.ConnectionError, requests.exceptions.Timeout):
        # Connection errors and timeouts are expected for valid URLs we can't reach
        if expected_exception:
            print(f'FAIL: {url} raised connection error instead of {expected_exception.__name__}')
        else:
            print(f'PASS: {url} is valid (got connection error as expected for unreachable host)')
    except Exception as e:
        if expected_exception and isinstance(e, expected_exception):
            print(f'PASS: {url} raised {type(e).__name__} as expected')
        else:
            print(f'FAIL: {url} raised unexpected {type(e).__name__}: {e}')
"

